'use strict';
// Verify the published source/data snapshot, then reproduce its generated bytes.
const fs=require('fs'),crypto=require('crypto'),assert=require('assert/strict'),{spawnSync}=require('child_process');
const sha=path=>crypto.createHash('sha256').update(fs.readFileSync(__dirname+'/'+path)).digest('hex');
const manifest=JSON.parse(fs.readFileSync(__dirname+'/manifest.json'));
for(const[path,expected]of Object.entries(manifest.files))assert.equal(sha(path),expected,'Snapshot mismatch: '+path);
const before=Object.fromEntries(['results.json','traces.json.gz'].map(p=>[p,sha(p)]));
const r=spawnSync(process.execPath,[__dirname+'/study.cjs'],{encoding:'utf8',timeout:60000});
assert.equal(r.status,0,r.stderr||r.stdout);
for(const[path,expected]of Object.entries(before))assert.equal(sha(path),expected,'Non-deterministic generated file: '+path);
console.log('Overlapping-prefix: frozen design, published hashes, 675 episodes, 120 authorization controls, and deterministic rerun PASS.');
